bool terminal_reset_request_id_exists_locked(const std::string& request_id) {
    return std::any_of(
        g_terminal_reset_responses.begin(), g_terminal_reset_responses.end(),
        [&](const TerminalResetResponse& cached) {
            return cached.request.request_id == request_id;
