void cache_terminal_reset_response_locked(
    const ResetRequest& request, const Json& document) {
    const auto existing = std::find_if(
        g_terminal_reset_responses.begin(), g_terminal_reset_responses.end(),
        [&](const TerminalResetResponse& cached) {
            return same_reset_identity(request, cached.request);
        });
    if (existing != g_terminal_reset_responses.end()) {
        g_terminal_reset_responses.erase(existing);
    }
    g_terminal_reset_responses.push_back(TerminalResetResponse{request, document});
    if (g_terminal_reset_responses.size() > kTerminalResetCacheLimit) {
        g_terminal_reset_responses.pop_front();
    }
}

Json make_reset_response(
    const ResetRequest& request, const char* status, const char* outcome_code,
    const std::string& detail) {
    return Json{
        {"schemaVersion", 1},
        {"responseSequence", ++g_reset_response_sequence},
        {"requestId", request.request_id},
        {"frameworkInstanceId", request.framework_instance_id},
        {"deploymentId", request.deployment_id},
        {"instrumentTreeHash", request.instrument_tree_hash},
        {"status", status},
        {"outcomeCode", outcome_code},
        {"detail", detail},
    };
}

Json make_reset_replay(Json response) {
    response["responseSequence"] = ++g_reset_response_sequence;
    return response;
}

void publish_reset_response(const Json& response) {
    const auto sequence = response.value("responseSequence", std::uint64_t{});
    std::lock_guard lock(g_reset_write_mutex);
    if (sequence < g_last_published_reset_response_sequence) return;
    if (write_control_json(kResetResponsePath, response)) {
        g_last_published_reset_response_sequence = sequence;
    }
}

void publish_terminal_reset_response(
    const ResetRequest& request, const char* outcome_code,
    const std::string& detail) {
    Json response;
    {
        std::lock_guard lock(g_reset_mutex);
        response = make_reset_response(request, "rejected", outcome_code, detail);
        cache_terminal_reset_response_locked(request, response);
    }
    publish_reset_response(response);
}

std::string required_control_string(
    const Json& document, const char* name, std::size_t maximum) {
    const auto found = document.find(name);
    if (found == document.end() || !found->is_string()) {
        throw std::runtime_error(std::string(name) + " must be a string");
    }
    const auto value = found->get<std::string>();
    if (value.empty() || value.size() > maximum) {
        throw std::runtime_error(std::string(name) + " has an invalid length");
    }
    return value;
}

bool safe_identity(const std::string& value) {
    return std::all_of(value.begin(), value.end(), [](unsigned char character) {
        return (character >= 'a' && character <= 'z') ||
            (character >= 'A' && character <= 'Z') ||
            (character >= '0' && character <= '9') ||
            character == '-' || character == '_' || character == '.' || character == ':';
    });
}

bool lowercase_sha256(const std::string& value) {
    return value.size() == 64 &&
        std::all_of(value.begin(), value.end(), [](unsigned char character) {
            return (character >= '0' && character <= '9') ||
                (character >= 'a' && character <= 'f');
        });
}

Json load_control_json(const char* relative) {
    const auto result = read_file(resolve_path(relative));
    if (result.status != ReadStatus::ok) {
        throw std::runtime_error(std::string(relative) + ": " + result.detail);
    }
    try {
        return Json::parse(result.bytes);
    } catch (const std::exception& error) {
        throw std::runtime_error(std::string(relative) + ": " + error.what());
    }
}

ResetRequest parse_reset_request() {
    const auto document = load_control_json(kResetRequestPath);
    if (!document.is_object() || document.value("schemaVersion", 0) != 1) {
        throw std::runtime_error("reset request schemaVersion must be 1");
    }
    ResetRequest request{
        required_control_string(document, "requestId", 128),
        required_control_string(document, "frameworkInstanceId", 128),
        required_control_string(document, "deploymentId", 128),
        required_control_string(document, "instrumentTreeHash", 64),
    };
    if (!safe_identity(request.request_id) ||
        !safe_identity(request.framework_instance_id) ||
        !safe_identity(request.deployment_id)) {
        throw std::runtime_error("reset request identity contains unsupported characters");
    }
    if (!lowercase_sha256(request.instrument_tree_hash)) {
        throw std::runtime_error("instrumentTreeHash must be lowercase SHA-256");
    }
    const auto delivery_attempt = document.find("deliveryAttempt");
    if (delivery_attempt != document.end() &&
        (!delivery_attempt->is_number_unsigned() ||
         delivery_attempt->get<std::uint64_t>() == 0)) {
        throw std::runtime_error("deliveryAttempt must be a positive integer");
    }
    return request;
}

bool on_script_reset_dispatched(bool accepted, void* context) {
    const auto token = static_cast<std::uint64_t>(
        reinterpret_cast<std::uintptr_t>(context));
    Json response;
    bool allow_reset = false;
    {
        std::lock_guard lock(g_reset_mutex);
        if (!g_pending_reset || g_pending_reset->token != token ||
            g_pending_reset->phase != ResetPhase::queued) {
            return false;
        }
        const auto request = g_pending_reset->request;
        if (!accepted) {
            response = make_reset_response(
                request, "rejected", "online_blocked",
                "REFramework blocked reset during an online match");
            cache_terminal_reset_response_locked(request, response);
            g_pending_reset.reset();
        } else if (g_pending_reset->lifecycle_epoch != g_lifecycle_epoch) {
            response = make_reset_response(
                request, "rejected", "lifecycle_superseded",
                "Lua lifecycle changed before the safe-frame dispatch");
            cache_terminal_reset_response_locked(request, response);
            g_pending_reset.reset();
        } else {
            g_pending_reset->phase = ResetPhase::accepted;
            response = make_reset_response(
                request, "accepted", "accepted",
                "REFramework accepted reset at a safe frame boundary");
            g_pending_reset->last_response = response;
            allow_reset = true;
        }
    }
    publish_reset_response(response);
    return allow_reset;
}

void process_reset_request() {
    if (!g_request_script_reset) return;
    ResetRequest request;
    try {
        request = parse_reset_request();
    } catch (const std::exception& error) {
        if (g_ref) g_ref->log_warn("[fgcnote_io] reset request rejected: %s", error.what());
        return;
    }

    // Multiple SF6 processes can resolve the same Proton-backed control
    // directory. Only the explicitly addressed framework instance may touch
    // the shared response file or its idempotency cache; a foreign process
    // must remain completely silent here.
    if (request.framework_instance_id != g_framework_instance_id) {
        if (g_ref) {
            g_ref->log_warn(
                "[fgcnote_io] reset request for another framework instance ignored");
        }
        return;
    }

    std::optional<Json> replay;
    bool identity_conflict = false;
    {
        std::lock_guard lock(g_reset_mutex);
        if (g_pending_reset &&
            same_reset_identity(request, g_pending_reset->request)) {
            replay = g_pending_reset->last_response;
        } else if (const auto* cached =
                       find_terminal_reset_response_locked(request)) {
            replay = *cached;
        } else if ((g_pending_reset &&
                    request.request_id == g_pending_reset->request.request_id) ||
                   terminal_reset_request_id_exists_locked(request.request_id)) {
            identity_conflict = true;
        }
    }
    if (replay) {
        publish_reset_response(make_reset_replay(std::move(*replay)));
        return;
    }
    if (identity_conflict) {
        publish_terminal_reset_response(
            request, "request_identity_conflict",
            "requestId was reused with different reset identity fields");
        return;
    }

    try {
        const auto deployment = load_control_json(kDeploymentPath);
        if (!deployment.is_object() ||
            deployment.value("deploymentId", std::string{}) != request.deployment_id ||
            deployment.value("instrumentTreeHash", std::string{}) != request.instrument_tree_hash) {
            publish_terminal_reset_response(
                request, "deployment_mismatch",
                "request does not match the active deployment marker");
            return;
        }
    } catch (const std::exception& error) {
        publish_terminal_reset_response(request, "deployment_marker_unavailable", error.what());
        if (g_ref) g_ref->log_warn("[fgcnote_io] reset request rejected: %s", error.what());
        return;
    }

    std::uint64_t token{};
    Json queued_response;
    {
        std::lock_guard lock(g_reset_mutex);
        if (g_pending_reset) {
            queued_response = make_reset_response(
                request, "rejected", "plugin_queue_busy",
                "another script reset is pending in the plugin");
            cache_terminal_reset_response_locked(request, queued_response);
        } else {
            token = ++g_reset_token_sequence;
            if (token == 0) token = ++g_reset_token_sequence;
            queued_response = make_reset_response(
                request, "queued", "queued",
                "waiting for the REFramework frame boundary");
            g_pending_reset = PendingReset{
                request, token, g_lifecycle_epoch, ResetPhase::queued, queued_response};
        }
    }
    publish_reset_response(queued_response);
    if (token == 0) return;

    const auto context = reinterpret_cast<void*>(static_cast<std::uintptr_t>(token));
    if (g_request_script_reset(on_script_reset_dispatched, context)) return;

    std::optional<Json> rejected;
    {
        std::lock_guard lock(g_reset_mutex);
        if (g_pending_reset && g_pending_reset->token == token &&
            g_pending_reset->phase == ResetPhase::queued) {
            rejected = make_reset_response(
                request, "rejected", "framework_queue_busy",
                "another REFramework reset request is queued");
            cache_terminal_reset_response_locked(request, *rejected);
            g_pending_reset.reset();
        }
    }
    if (rejected) publish_reset_response(*rejected);
}

