    def start(self, args) -> dict:
        task_id = self.assert_task_id(args.task)
        if not args.title:
            raise CommandError("Pass -Title for a new task.")
        if not args.owner:
            raise CommandError("Pass -Owner for a new task.")
        repo = self.repo_path(args.repo)
        base = args.base or REPOS[args.repo][1]
        branch = args.branch or f"agent/{task_id}"
        output = self.git.run(repo, "rev-parse", "--verify", f"{base}^{{commit}}")
        if not output:
            raise CommandError(f"Could not resolve base '{base}'.")
        base_revision = output[0]
        worktree = None
        if args.create_worktree:
            worktree = (Path(args.worktree).resolve() if args.worktree else
                        (self.root / ".agent-worktrees" / args.repo / task_id).resolve())
        elif args.worktree:
            worktree = Path(args.worktree).resolve()
        now = self.clock.timestamp()
        session_id = (args.session or os.environ.get("CODEX_THREAD_ID")
                      or os.environ.get("CLAUDE_CODE_SESSION_ID")
                      or os.environ.get("CLAUDE_SESSION_ID"))
        session_client = args.session_client
        if not session_client and session_id:
            if os.environ.get("CODEX_THREAD_ID") == session_id:
                session_client = "codex"
            elif session_id in {
                os.environ.get("CLAUDE_CODE_SESSION_ID"), os.environ.get("CLAUDE_SESSION_ID")
            }:
                session_client = "claude-code"
            else:
                session_client = "external"
        session_label = args.session_label or args.title
        with self.store.transaction():
            if self.store.connection.execute("SELECT 1 FROM tasks WHERE id = ?", (task_id,)).fetchone():
                raise CommandError(f"Task '{task_id}' already exists.")
            self.store.connection.execute(
                "INSERT INTO tasks(id,title,owner,session_client,session_id,session_label,repo,status,"
                "base,base_revision,branch,worktree,head_revision,summary,created_at,updated_at,heartbeat_at) "
                "VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                (task_id, args.title, args.owner, session_client, session_id, session_label, args.repo,
                 "preparing" if args.create_worktree else "running", base, base_revision,
                 branch, str(worktree) if worktree else None, None, None, now, now, now),
            )
            self.store.add_event(task_id, "task.started", {
                "owner": args.owner, "repo": args.repo, "branch": branch,
                "baseRevision": base_revision, "sessionClient": session_client,
                "sessionId": session_id, "sessionLabel": session_label,
            })
        if args.create_worktree:
            created = False
            try:
                if worktree.exists() or worktree.is_symlink():
                    raise CommandError(f"Worktree path already exists: {worktree}")
                worktree.parent.mkdir(parents=True, exist_ok=True)
                self.git.run(repo, "worktree", "add", "-b", branch, str(worktree), base)
                created = True
                with self.store.transaction():
                    self.store.connection.execute(
                        "UPDATE tasks SET status='running', updated_at=? WHERE id=?",
                        (self.clock.timestamp(), task_id),
                    )
                    self.store.add_event(task_id, "worktree.created",
                                         {"path": str(worktree), "branch": branch})
            except Exception as exc:
                compensation = None
                if created:
                    try:
                        self.git.run(repo, "worktree", "remove", "--force", str(worktree))
                        self.git.run(repo, "branch", "-D", branch)
                        compensation = "created worktree and branch removed"
                    except Exception as cleanup_exc:
                        compensation = f"manual recovery required: {cleanup_exc}"
                reason = f"Worktree creation failed: {exc}"
                if compensation:
                    reason += f"; compensation: {compensation}"
                with self.store.transaction():
                    self.store.connection.execute(
                        "UPDATE tasks SET status='failed', summary=?, updated_at=? WHERE id=?",
                        (reason, self.clock.timestamp(), task_id),
                    )
                    self.store.add_event(task_id, "task.failed", {"reason": reason})
                raise
        return self.store.row_task(self.store.task(task_id))

