    @staticmethod
    def _managed_args(args, *, task: str | None = None) -> argparse.Namespace:
        values = vars(args).copy()
        if task is not None:
            values["task"] = task
        values["queue_managed"] = True
        return argparse.Namespace(**values)

    def _claim_slot(self, runtime_id: str, task_id: str,
                    replacing_task: str | None = None) -> None:
        resources = (f"runtime:{runtime_id}/deployment", f"runtime:{runtime_id}/session")
        with self.store.transaction():
            self.store.expire_claims()
            allowed = {task_id}
            if replacing_task:
                allowed.add(replacing_task)
            conflicts = self.store.connection.execute(
                "SELECT task_id, resource FROM claims WHERE resource IN (?,?)",
                resources,
            ).fetchall()
            conflicts = [row for row in conflicts if row["task_id"] not in allowed]
            if conflicts:
                owners = ", ".join(f"{row['task_id']}[{row['resource']}]" for row in conflicts)
                raise NotReadyError(f"SF6 live test slot is still owned by {owners}")
            now = self.clock.timestamp()
            expires = (self.clock.now() + dt.timedelta(seconds=900)).isoformat(
                timespec="microseconds").replace("+00:00", "Z")
            self.store.connection.execute(
                "DELETE FROM claims WHERE resource IN (?,?)", resources,
            )
            for resource in resources:
                self.store.connection.execute(
                    "INSERT INTO claims VALUES(?,?,?,?,?)",
                    (task_id, resource, "write", now, expires),
                )

    def _renew_current(self, runtime_id: str) -> None:
        row = self._current(runtime_id)
        if not row:
            return
        expires = (self.clock.now() + dt.timedelta(seconds=900)).isoformat(
            timespec="microseconds").replace("+00:00", "Z")
        with self.store.transaction():
            self.store.connection.execute(
                "UPDATE claims SET expires_at=? WHERE task_id=? AND resource IN (?,?)",
                (expires, row["task_id"], f"runtime:{runtime_id}/deployment",
                 f"runtime:{runtime_id}/session"),
            )
            self.store.connection.execute(
                "UPDATE tasks SET heartbeat_at=?, updated_at=? WHERE id=?",
                (self.clock.timestamp(), self.clock.timestamp(), row["task_id"]),
            )

