    def _set_needs_operator(self, test_id: str, kind: str, prompt: str,
                            deployment_id: str | None = None,
                            native_request: dict | None = None) -> sqlite3.Row:
        stored_kind = "activation" if kind == "native_reset_pending" else kind
        request_json = (
            json.dumps(native_request, ensure_ascii=False, separators=(",", ":"))
            if native_request is not None else None
        )
        with self.store.transaction():
            now = self.clock.timestamp()
