    def _mark_terminal(self, test_id: str, result: str, summary: str) -> sqlite3.Row:
        with self.store.transaction():
            now = self.clock.timestamp()
            self.store.connection.execute(
                "UPDATE live_tests SET state=?, result=?, summary=?, checkpoint_kind=NULL, "
                "operator_prompt=NULL, pending_result=NULL, native_reset_request_json=NULL, "
                "finished_at=?, updated_at=? WHERE id=?",
                (result, result, summary, now, now, test_id),
            )
            row = self._row(test_id)
            event = "runtime.test.cancelled" if result == "cancelled" else "runtime.test.finished"
            self._event(row, event, {"result": result, "summary": summary})
            return row

    @staticmethod
    def _json_object(path: Path) -> dict | None:
        try:
            value = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            return None
        return value if isinstance(value, dict) else None

    def _reset_capability(self, source: Path) -> dict | None:
        value = self._json_object(source / self.RESET_CONTROL_ROOT / "capability.json")
        if not value or value.get("schemaVersion") != 1:
            return None
        instance = value.get("frameworkInstanceId")
        extension = value.get("extension")
        extension_version = extension.get("version") if isinstance(extension, dict) else None
        if (not isinstance(instance, str) or not instance
                or not isinstance(extension, dict)
                or extension.get("name") != self.RESET_EXTENSION_NAME
                or not isinstance(extension_version, int)
                or isinstance(extension_version, bool)
                or extension_version != self.RESET_EXTENSION_VERSION):
            return None
        return value

    @staticmethod
    def _reset_identity_matches(value: dict, expected: dict) -> bool:
        return all(value.get(key) == expected[key] for key in (
            "requestId", "frameworkInstanceId", "deploymentId", "instrumentTreeHash",
        ))

    def _native_timeout(self, args) -> float:
        # `runtime-test-request -TimeoutSeconds` is also a useful deterministic
        # test/diagnostic override. Later wait/watch actions retain their own
        # established timeout meaning and use the production reset bound.
        if args.action == "runtime-test-request" and args.timeout_seconds is not None:
            if args.timeout_seconds < 0:
                raise CommandError("-TimeoutSeconds cannot be negative.")
            return float(args.timeout_seconds)
        return self.NATIVE_RESET_TIMEOUT_SECONDS

    def _native_reset_guard(self, deployment: sqlite3.Row, timeout: float = 30.0):
        path = (self.store.runtime / "live" / deployment["runtime_id"] /
                "native-reset-locks" / f"{deployment['id']}.lock")
        return legacy_lock(path, timeout=timeout)

    def _native_pending_event_exists(self, test_id: str) -> bool:
        return bool(self.store.connection.execute(
            "SELECT 1 FROM events WHERE type='runtime.test.needs_operator' "
            "AND json_extract(payload_json,'$.testId')=? "
            "AND json_extract(payload_json,'$.checkpointKind')='native_reset_pending' "
            "LIMIT 1",
            (test_id,),
        ).fetchone())

    def _publish_interrupted_native_pending(self, runtime_id: str) -> bool:
        row = self._current(runtime_id)
        if (not row or row["state"] != "needs_operator"
                or row["native_reset_request_json"] is None):
            return True
        if self._native_pending_event_exists(row["id"]):
            return True
        deployment = self.runtime._deployment(row["deployment_id"])
        if not deployment:
            return False
        try:
            # The normal delivery path owns this lock through its final state
            # transition.  Acquiring it non-blocking proves that path is no
            # longer running (normally completed, or interrupted by a crash).
            with self._native_reset_guard(deployment, timeout=0):
                with self.store.transaction():
                    row = self._row(row["id"])
                    if (row["state"] != "needs_operator"
                            or row["native_reset_request_json"] is None
                            or self._native_pending_event_exists(row["id"])):
                        return True
                    self._event(row, "runtime.test.needs_operator", {
                        "checkpointKind": "native_reset_pending",
                        "operatorPrompt": row["operator_prompt"],
                        "completionCriteria": row["completion_criteria"],
                        "recoveredAfterInterruption": True,
                    })
                    return True
        except CommandError:
            # A live delivery loop still owns the guard and will either finish
            # automatically or publish the canonical pending event itself.
            return False

    def _persist_native_reset_attempt(self, row: sqlite3.Row,
                                      deployment: sqlite3.Row,
                                      request: dict) -> None:
        # Persist before the first filesystem delivery.  If this CLI is
        # interrupted afterwards, confirm/cancel can still resume from the
        # exact request identity instead of leaving the FIFO head in preparing.
        prompt = self._native_pending_prompt(
            "request delivery has not reached a terminal response")
        request_json = json.dumps(
            request, ensure_ascii=False, separators=(",", ":"))
        with self.store.transaction():
            self.store.connection.execute(
                "UPDATE live_tests SET state='needs_operator', checkpoint_kind='activation', "
                "operator_prompt=?, deployment_id=?, native_reset_request_json=?, updated_at=? "
                "WHERE id=?",
                (prompt, deployment["id"], request_json,
                 self.clock.timestamp(), row["id"]),
            )

    def _try_native_reset(self, row: sqlite3.Row, args, prior: dict,
                          deployment_id: str) -> tuple[str, str, dict | None]:
        deployment = self.runtime._deployment(deployment_id)
        if not deployment:
            return "fallback", "deployment disappeared before native reset", None
        source = Path(deployment["target"])
        timeout = self._native_timeout(args)
        deadline = self.monotonic() + timeout
        capability = None
        while True:
            candidate = self._reset_capability(source)
            if (candidate and candidate.get("available") is True
                    and candidate["frameworkInstanceId"] == prior["frameworkInstanceId"]):
                capability = candidate
                break
            if self.monotonic() >= deadline:
                return "fallback", "matching native reset capability did not appear", None
            self.sleep(self.NATIVE_RESET_POLL_SECONDS)

        request_id = f"reset-{uuid.uuid4().hex}"
        request = {
            "schemaVersion": 1,
            "requestId": request_id,
            "frameworkInstanceId": capability["frameworkInstanceId"],
            "deploymentId": deployment["id"],
            "instrumentTreeHash": deployment["source_tree_hash"],
            "deliveryAttempt": 1,
        }
        self._persist_native_reset_attempt(row, deployment, request)
        request_path = source / self.RESET_CONTROL_ROOT / "request.json"
        try:
            self.runtime._write_json(request_path, request)
        except OSError as exc:
            observed = self._json_object(request_path)
            if (observed and observed.get("schemaVersion") == 1
                    and self._reset_identity_matches(observed, request)):
                return (
                    "pending",
                    f"native reset request write result is uncertain: {exc}",
                    request,
                )
            return "fallback", f"native reset request write failed: {exc}", None

        last_detail = "native reset response did not arrive"
        response_path = source / self.RESET_CONTROL_ROOT / "response.json"
        for delivery_attempt in (1, 2):
            if delivery_attempt == 2:
                request = {**request, "deliveryAttempt": 2}
                try:
                    # The retry changes only delivery metadata.  The plugin can
                    # replay a cached terminal response for the same identity
                    # without scheduling a second reset.
                    self.runtime._write_json(request_path, request)
                except OSError as exc:
                    return (
                        "pending",
                        f"native reset retry write result is uncertain: {exc}",
                        request,
                    )

            deadline = self.monotonic() + timeout
            while True:
                response = self._json_object(response_path)
                if response and response.get("requestId") == request_id:
                    if (response.get("schemaVersion") != 1
                            or not self._reset_identity_matches(response, request)):
                        return (
                            "pending",
                            "native reset response provenance mismatch",
                            request,
                        )
                    status = response.get("status")
                    detail = response.get("detail")
                    if isinstance(detail, str) and detail:
                        last_detail = detail
                    if status == "rejected":
                        outcome_code = response.get("outcomeCode")
                        if outcome_code in self.SAFE_NATIVE_RESET_REJECTIONS:
                            return "fallback", last_detail, request
