                        managed = self._managed_args(args, task=row["task_id"])
                        managed.require_handshake = True
                        try:
                            self.runtime.activate(managed)
                        except CommandError as exc:
                            last_detail = str(exc)
                        else:
                            return (
                                "completed",
                                "native reset and deployment handshake completed",
                                request,
                            )
                    elif status not in {"queued", "accepted", "destroyed"}:
                        return (
                            "pending",
                            f"unknown native reset response status {status!r}",
                            request,
                        )
                if self.monotonic() >= deadline:
                    break
                self.sleep(self.NATIVE_RESET_POLL_SECONDS)
        return "pending", last_detail, request

