                "UPDATE live_tests SET state='testing', checkpoint_kind=NULL, operator_prompt=NULL, "
                "native_reset_request_json=NULL, started_at=COALESCE(started_at,?), "
                "updated_at=? WHERE id=?",
                (now, now, test_id),
