                now = self.clock.timestamp()
                self.store.connection.execute(
                    "UPDATE live_tests SET state='failed', result='failed', summary=?, "
                    "finished_at=?, updated_at=? WHERE id=?",
                    (f"deployment failed: {exc}", now, now, row["id"]),
