                failed = self._row(row["id"])
                self._event(failed, "runtime.test.failed", {"reason": str(exc)})
                current = self.runtime._runtime(row["runtime_id"])
                if current["state"] == "released":
                    self.store.connection.execute(
                        "DELETE FROM claims WHERE task_id=? AND resource IN (?,?)",
                        (row["task_id"], f"runtime:{row['runtime_id']}/deployment",
