            self, runtime: sqlite3.Row, queued: sqlite3.Row | None) -> bool:
        """Allow the same task to supersede one legacy, unlinked deployment."""
        if (not queued or runtime["state"] != "active"
                or runtime["owner_task_id"] != queued["task_id"]
                or not runtime["active_deployment_id"]):
            return False
        claims = self.store.connection.execute(
            "SELECT 1 FROM claims WHERE resource IN (?,?) LIMIT 1",
            (f"runtime:{runtime['id']}/deployment",
             f"runtime:{runtime['id']}/session"),
        ).fetchone()
        if claims:
            return False
        deployment = self.runtime._deployment(runtime["active_deployment_id"])
        if (not deployment or deployment["state"] != "active"
                or deployment["owner_task_id"] != queued["task_id"]):
            return False
        latest = self.store.connection.execute(
            "SELECT deployment_id FROM live_tests WHERE runtime_id=? AND task_id=? "
            "AND state IN ('passed','failed','inconclusive','cancelled') "
            "ORDER BY queue_order DESC LIMIT 1",
            (runtime["id"], queued["task_id"]),
        ).fetchone()
        if not latest or latest["deployment_id"] is not None:
            return False
        try:
            actual = self.runtime._validate_current(runtime)
            _task, _worktree, source = self.runtime._task_source(queued["task_id"])
