const FGCNoteREFrameworkExtensionV1* discover_reset_extension(
    const REFrameworkPluginInitializeParam* parameter) {
    HMODULE framework_module{};
    if (!GetModuleHandleExW(
            GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS |
                GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,
            reinterpret_cast<LPCWSTR>(parameter->functions),
            &framework_module)) {
        return nullptr;
    }
    const auto exported = GetProcAddress(
        framework_module, FGCNOTE_REFRAMEWORK_EXTENSION_QUERY);
    if (!exported) return nullptr;

    FGCNoteQueryREFrameworkExtensionV1 query{};
    static_assert(sizeof(query) == sizeof(exported));
    std::memcpy(&query, &exported, sizeof(query));
    const auto* extension = query();
    if (!extension ||
        extension->magic != FGCNOTE_REFRAMEWORK_EXTENSION_MAGIC ||
        extension->size < sizeof(FGCNoteREFrameworkExtensionV1) ||
        extension->version != FGCNOTE_REFRAMEWORK_EXTENSION_VERSION ||
        !extension->request_script_reset) {
        return nullptr;
    }
    return extension;
}

