ResetControl parse_reset_control() {
    const auto document = load_control_json(kResetRequestPath);
    if (!document.is_object() || document.value("schemaVersion", 0) != 1) {
        throw std::runtime_error("reset request schemaVersion must be 1");
    }
    const auto kind = required_control_string(document, "kind", 16);
    const auto command = kind == "reset" ? ResetCommand::reset :
        kind == "cancel" ? ResetCommand::cancel :
        throw std::runtime_error("reset request kind must be reset or cancel");
    const auto generation = document.find("holderGeneration");
    if (generation == document.end() || !generation->is_number_unsigned() ||
        generation->get<std::uint64_t>() == 0) {
        throw std::runtime_error("holderGeneration must be a positive integer");
    }
    ResetRequest request{
        required_control_string(document, "requestId", 128),
        required_control_string(document, "frameworkInstanceId", 128),
        required_control_string(document, "deploymentId", 128),
        required_control_string(document, "instrumentTreeHash", 64),
        generation->get<std::uint64_t>(),
    };
    if (!safe_identity(request.request_id) ||
        !safe_identity(request.framework_instance_id) ||
        !safe_identity(request.deployment_id)) {
        throw std::runtime_error("reset request identity contains unsupported characters");
    }
    if (!lowercase_sha256(request.instrument_tree_hash)) {
        throw std::runtime_error("instrumentTreeHash must be lowercase SHA-256");
    }
    const auto delivery_attempt = document.find("deliveryAttempt");
    if (delivery_attempt != document.end() &&
        (!delivery_attempt->is_number_unsigned() ||
         delivery_attempt->get<std::uint64_t>() == 0)) {
        throw std::runtime_error("deliveryAttempt must be a positive integer");
    }
    return ResetControl{command, std::move(request)};
}

