    const auto token = static_cast<std::uint64_t>(
        reinterpret_cast<std::uintptr_t>(context));
    std::optional<ResetControl> current;
    try {
        // request.json is the durable holder authority. runtime-done replaces
        // reset with cancel before releasing ownership, so this final reread
        // fences a callback which reached REFramework after its holder left.
        current = parse_reset_control();
    } catch (...) {
        // An unavailable authority can never authorize process mutation.
