            response = make_reset_response(
                request, "rejected", "lifecycle_superseded",
                "Lua lifecycle changed before the safe-frame dispatch");
            cache_terminal_reset_response_locked(request, response);
            g_pending_reset.reset();
        } else {
            // This transition is the linearization point: once accepted is
            // published, a concurrent cancellation must wait for completion.
            g_pending_reset->phase = ResetPhase::accepted;
            response = make_reset_response(
                request, "accepted", "accepted",
