const FGCNoteREFrameworkExtensionV1* discover_reset_extension(
    const REFrameworkPluginInitializeParam* parameter) {
    HMODULE framework_module{};
    if (!GetModuleHandleExW(
            GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS |
                GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,
            reinterpret_cast<LPCWSTR>(parameter->functions),
            &framework_module)) {
        return nullptr;
    }
    const auto exported = GetProcAddress(
        framework_module, FGCNOTE_REFRAMEWORK_EXTENSION_QUERY);
    if (!exported) return nullptr;

    FGCNoteQueryREFrameworkExtensionV1 query{};
    static_assert(sizeof(query) == sizeof(exported));
    std::memcpy(&query, &exported, sizeof(query));
    const auto* extension = query();
    if (!extension ||
        extension->magic != FGCNOTE_REFRAMEWORK_EXTENSION_MAGIC ||
        extension->size < sizeof(FGCNoteREFrameworkExtensionV1) ||
        extension->version != FGCNOTE_REFRAMEWORK_EXTENSION_VERSION ||
        !extension->request_script_reset) {
        return nullptr;
    }
    return extension;
}

void publish_reset_capability() {
    const auto available = g_request_script_reset != nullptr;
    write_control_json(kResetCapabilityPath, Json{
        {"schemaVersion", 1},
        {"available", available},
        {"pluginVersion", kPluginVersion},
        {"frameworkInstanceId", g_framework_instance_id},
        {"frameworkApi", {
            {"major", g_framework_version.major},
            {"minor", g_framework_version.minor},
            {"patch", g_framework_version.patch},
        }},
        {"extension", {
            {"name", "fgcnote.script-reset"},
            {"version", g_reset_extension_version},
        }},
        {"holderGenerationFencing", available},
        {"reason", available ? "available" : "fgcNote REFramework extension v1 is unavailable"},
    });
}

bool same_reset_identity(const ResetRequest& left, const ResetRequest& right) {
    return left.request_id == right.request_id &&
        left.framework_instance_id == right.framework_instance_id &&
        left.deployment_id == right.deployment_id &&
        left.instrument_tree_hash == right.instrument_tree_hash &&
        left.holder_generation == right.holder_generation;
}

const Json* find_terminal_reset_response_locked(const ResetRequest& request) {
    const auto found = std::find_if(
        g_terminal_reset_responses.rbegin(), g_terminal_reset_responses.rend(),
        [&](const TerminalResetResponse& cached) {
            return same_reset_identity(request, cached.request);
        });
    return found == g_terminal_reset_responses.rend() ? nullptr : &found->document;
}

bool terminal_reset_request_id_exists_locked(const std::string& request_id) {
    return std::any_of(
        g_terminal_reset_responses.begin(), g_terminal_reset_responses.end(),
        [&](const TerminalResetResponse& cached) {
            return cached.request.request_id == request_id;
        });
}

void cache_terminal_reset_response_locked(
    const ResetRequest& request, const Json& document) {
    const auto existing = std::find_if(
        g_terminal_reset_responses.begin(), g_terminal_reset_responses.end(),
        [&](const TerminalResetResponse& cached) {
            return same_reset_identity(request, cached.request);
        });
    if (existing != g_terminal_reset_responses.end()) {
        g_terminal_reset_responses.erase(existing);
    }
    g_terminal_reset_responses.push_back(TerminalResetResponse{request, document});
    if (g_terminal_reset_responses.size() > kTerminalResetCacheLimit) {
        g_terminal_reset_responses.pop_front();
    }
}

Json make_reset_response(
    const ResetRequest& request, const char* status, const char* outcome_code,
    const std::string& detail) {
    return Json{
        {"schemaVersion", 1},
        {"responseSequence", ++g_reset_response_sequence},
        {"requestId", request.request_id},
        {"frameworkInstanceId", request.framework_instance_id},
        {"deploymentId", request.deployment_id},
        {"instrumentTreeHash", request.instrument_tree_hash},
        {"holderGeneration", request.holder_generation},
        {"status", status},
        {"outcomeCode", outcome_code},
        {"detail", detail},
    };
}

Json make_reset_replay(Json response) {
    response["responseSequence"] = ++g_reset_response_sequence;
    return response;
}

void publish_reset_response(const Json& response) {
    const auto sequence = response.value("responseSequence", std::uint64_t{});
