def native_fencing_simulator(self, fixture: RuntimeFixture, instance: str,
                             *, accepted_before_cancel: bool = False):
    errors: list[BaseException] = []
    observed: list[dict] = []

    def wait_for_value(path: Path, predicate) -> dict:
        deadline = time.monotonic() + 8
        while time.monotonic() < deadline:
            try:
                value = json.loads(path.read_text(encoding="utf-8"))
            except (OSError, json.JSONDecodeError):
                time.sleep(0.01)
                continue
            if predicate(value):
                return value
            time.sleep(0.01)
        raise AssertionError(f"timed out waiting for fenced value at {path}")

    def simulate() -> None:
        try:
            source = fixture.task_worktree / "reframework"
            marker_path = source / "data/fgcnote/devtools/deployment.json"
            marker = wait_for_value(marker_path, lambda value: "deploymentId" in value)
            self.publish_reset_capability(source, instance)
            request_path = source / self.RESET_ROOT / "request.json"
            request = wait_for_value(
                request_path, lambda value: value.get("kind") == "reset")
            observed.append(request)
            self.write_json(source / self.RESET_ROOT / "response.json", {
                **request,
                "status": "accepted" if accepted_before_cancel else "queued",
                "outcomeCode": "accepted" if accepted_before_cancel else "queued",
                "detail": "simulated safe-frame state",
            })
            cancellation = wait_for_value(
                request_path,
                lambda value: value.get("kind") == "cancel"
                and value.get("requestId") == request["requestId"],
            )
            observed.append(cancellation)
            if accepted_before_cancel:
                time.sleep(0.1)
                self.write_json(source / self.RESET_ROOT / "response.json", {
                    **request, "status": "completed", "outcomeCode": "completed",
                    "detail": "irreversible reset completed",
                })
                self.write_json(
                    source / "data/fgcnote/devtools/deployment-handshake.json", {
                        "schemaVersion": 1,
                        "deploymentId": marker["deploymentId"],
                        "processNonce": "fenced-process",
                        "scriptGeneration": 2,
                        "instrumentCommit": marker["instrumentCommit"],
                        "instrumentDirty": marker["instrumentDirty"],
                        "instrumentTreeHash": marker["instrumentTreeHash"],
                        "sf6BuildId": marker["sf6BuildId"],
                    })
            else:
                self.write_json(source / self.RESET_ROOT / "response.json", {
                    **request, "status": "cancelled", "outcomeCode": "holder_released",
                    "detail": "queued reset cancelled",
                })
        except BaseException as exc:
            errors.append(exc)

    thread = threading.Thread(target=simulate, daemon=True)
    thread.start()
    return thread, errors, observed

