TASK_ID = re.compile(r"^[a-z0-9][a-z0-9._-]{1,63}$")
SF6_EXECUTABLE = "streetfighter6.exe"
RESET_CONTROL_ROOT = Path("data/fgcnote/devtools/script-reset")
RESET_IDENTITY_KEYS = (
    "requestId", "frameworkInstanceId", "deploymentId",
    "instrumentTreeHash", "holderGeneration",
)
RESET_TERMINAL = frozenset({"cancelled", "completed", "rejected"})
RESET_IRREVERSIBLE = frozenset({"accepted", "destroyed"})
RESET_SAFE_REJECTIONS = frozenset({
    "online_blocked", "deployment_mismatch", "deployment_marker_unavailable",
    "instrument_tree_mismatch", "invalid_request", "holder_superseded",
})
NATIVE_FENCE_TIMEOUT_SECONDS = 5.0


def json_object(path: Path) -> dict | None:
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return None
    return value if isinstance(value, dict) else None


def reset_identity_matches(value: dict, expected: dict) -> bool:
    return all(value.get(key) == expected.get(key) for key in RESET_IDENTITY_KEYS)


def reset_cancel_document(request: dict) -> dict:
    return {**request, "kind": "cancel", "cancellationAttempt": 1}


def reset_terminal_safety(response: dict | None,
                          request: dict) -> tuple[bool, bool, str | None]:
    """Return safe-terminal, real-hazard and status for one reset identity."""
    if not response or not reset_identity_matches(response, request):
        return False, False, None
    status = response.get("status")
    if status in {"cancelled", "completed"}:
        return True, False, status
    if status == "rejected":
        return (
            (True, False, status)
            if response.get("outcomeCode") in RESET_SAFE_REJECTIONS
            else (False, True, status)
        )
    if status in RESET_IRREVERSIBLE:
        return False, True, status
    if isinstance(status, str) and status != "queued":
        return False, True, status
    return False, False, status if isinstance(status, str) else None


def pending_reset_observation(connection: sqlite3.Connection,
                              row: sqlite3.Row | None) -> tuple[str | None, bool]:
    if not row or row["native_reset_request_json"] is None:
        return None, False
    try:
        request = json.loads(row["native_reset_request_json"])
    except (TypeError, json.JSONDecodeError):
        return "legacy_unknown", True
    deployment = connection.execute(
        "SELECT target FROM deployments WHERE id=?", (row["deployment_id"],),
    ).fetchone()
    if not deployment:
        return "legacy_unknown", True
    response = json_object(
        Path(deployment["target"]) / RESET_CONTROL_ROOT / "response.json")
    _safe, hazard, status = reset_terminal_safety(response, request)
    return status or "queued", hazard


